const TODAY='8 noiembrie 2026';
const ARTICLES=[
{id:'rapid-arges',cat:'Liga 1',code:'L1',date:'19 septembrie 2026',title:'Rapid 3-1 FC Argeș: giuleștenii au rezolvat meciul în final',dek:'Rapid a trecut de FC Argeș cu 3-1 în etapa a 10-a, într-un meci decis în ultimele minute.',source:'GSP',url:'https://www.gsp.ro/fotbal/liga-1/rapid-fc-arges-echipe-probabile-superliga-979947.html',body:[['p','Rapid a învins FC Argeș cu 3-1 în etapa a 10-a din SuperLiga și a urcat temporar pe primul loc al clasamentului. Meciul a avut un final spectaculos, iar giuleștenii au găsit resursele necesare pentru a transforma avantajul într-o victorie clară.'],['h2','Andrei Șucu a închis partida'],['p','Unul dintre momentele importante ale serii a fost golul lui Andrei Șucu. Execuția tânărului atacant a atras atenția imediat după meci, inclusiv prin analiza făcută de Ilie Dumitrescu.'],['h2','Trei puncte înaintea pauzei internaționale'],['p','Victoria vine înaintea ferestrei internaționale și îi oferă Rapidului un avantaj de moment în clasament. FC Argeș a rămas în joc în bună parte din partidă, însă echipa gazdă a fost mai eficientă în momentele decisive.']]},
{id:'craiova-fcsb',cat:'Liga 1',code:'L1',date:'19 septembrie 2026',title:'Universitatea Craiova – FCSB: derby-ul care poate schimba ierarhia',dek:'Etapa a 10-a aduce unul dintre cele mai așteptate dueluri ale weekendului din SuperLiga.',source:'SuperLiga / LPF',url:'https://www.superliga.ro/articole/cunoastem-programul-superligii-pentru-sezonul-20262027-f9b16479',body:[['p','Universitatea Craiova și FCSB se întâlnesc în etapa a 10-a, într-un duel cu miză importantă pentru zona superioară a campionatului. Programul oficial al LPF confirmă partida pentru 19 septembrie.'],['h2','Un meci cu presiune mare'],['p','În astfel de dueluri, diferențele sunt adesea date de eficiența din careu, fazele fixe și capacitatea de a gestiona momentele de presiune. Pentru ambele formații, punctele pot conta mult în perspectiva următoarelor etape.']]},
{id:'cfr-botosani',cat:'Liga 1',code:'L1',date:'19 septembrie 2026',title:'CFR Cluj – FC Botoșani: duelul care deschide ziua în SuperLiga',dek:'CFR primește vizita lui FC Botoșani într-o etapă cu mai multe meciuri importante.',source:'SuperLiga / LPF',url:'https://www.superliga.ro/articole/cunoastem-programul-superligii-pentru-sezonul-20262027-f9b16479',body:[['p','Programul etapei a 10-a din SuperLiga include sâmbătă duelul CFR Cluj – FC Botoșani. Partida face parte dintr-o rundă în care echipele din partea superioară și formațiile aflate în cursa pentru puncte au meciuri cu miză.'],['h2','Contextul etapei'],['p','Înaintea unei serii de meciuri directe între formațiile cu obiective diferite, fiecare punct câștigat poate influența pozițiile din clasament și abordarea următoarelor etape.']]},
{id:'nationala-lot',cat:'Naționala',code:'RO',date:'18 septembrie 2026',title:'Hagi a anunțat lotul României pentru primele patru meciuri din Nations League',dek:'Selecționerul a convocat 33 de jucători pentru prima fereastră oficială a noului mandat.',source:'FRF',url:'https://www.frf.ro/nationale/masculin/echipa-nationala/gheorghe-hagi-a-stabilit-lotul-romaniei-pentru-primele-patru-meciuri-din-liga-natiunilor/',body:[['p','Gheorghe Hagi a anunțat pe 18 septembrie lotul de 33 de jucători pentru primele patru partide din Liga Națiunilor 2026/27. Lista include fotbaliști din campionate precum Spania, Italia, Anglia, Belgia, Germania și Turcia, dar și jucători din SuperLiga.'],['h2','Patru meciuri într-o perioadă scurtă'],['p','România va juca pe 25 septembrie în Suedia, pe 28 septembrie acasă cu Bosnia și Herțegovina, pe 2 octombrie în Polonia și pe 5 octombrie din nou cu Suedia. Partida cu Bosnia este programată fără spectatori.']]},
{id:'nationala-program',cat:'Naționala',code:'RO',date:'18 septembrie 2026',title:'Suedia – România deschide seria de patru meciuri: Hagi are 11 zile pentru patru partide',dek:'Programul din Nations League pune accent pe recuperare, deplasări și gestionarea lotului.',source:'FRF / GSP',url:'https://www.gsp.ro/fotbal/nationala/programul-atipic-pe-care-l-a-stabilit-hagi-pentru-meciul-cu-suedia-980264.html',body:[['p','Prima partidă a României este programată pe 25 septembrie, la Stockholm. Fereastra FIFA continuă cu Bosnia, Polonia și Suedia, astfel că stafful trebuie să gestioneze un calendar dens.'],['h2','Logistica devine parte din pregătire'],['p','Într-o asemenea succesiune, minutele jucătorilor, recuperarea și deplasările pot influența alegerile selecționerului. Hagi are la dispoziție un lot numeros tocmai pentru a putea ajusta formula de la un meci la altul.']]},
{id:'pl-brentford-chelsea',cat:'Premier League',code:'PL',date:'18 septembrie 2026',title:'Brentford 3-0 Chelsea: seara în care gazdele au rupt meciul după pauză',dek:'Brentford a marcat de trei ori și a obținut o victorie clară în etapa a cincea.',source:'The Guardian',url:'https://www.theguardian.com/football/live/2026/sep/18/brentford-v-chelsea-premier-league-live-score-updates',body:[['p','Brentford a învins Chelsea cu 3-0, într-un meci care a rămas strâns înainte de pauză. După reluare, gazdele au găsit spații și au transformat avantajul într-un succes categoric.'],['h2','Anthony, Thiago și Carvalho pe tabelă'],['p','Jaidon Anthony a deschis scorul, Thiago a majorat diferența, iar Fabio Carvalho a închis tabela în prelungiri. Rezultatul schimbă tonul începutului de sezon pentru Chelsea și confirmă capacitatea lui Brentford de a pune probleme adversarilor mari.']]},
{id:'pl-tottenham-villa',cat:'Premier League',code:'PL',date:'19 septembrie 2026',title:'Tottenham – Aston Villa: duelul pentru primul succes al uneia dintre cele două echipe',dek:'Londra găzduiește unul dintre meciurile cu cea mai mare miză psihologică din etapa a cincea.',source:'Premier League',url:'https://www.premierleague.com/en/news/4719983/ten-key-questions-for-matchweeks-fixtures',body:[['p','Tottenham și Aston Villa se întâlnesc sâmbătă, iar analiza oficială a Premier League include partida printre punctele centrale ale etapei. Ambele echipe caută un rezultat care să le ridice nivelul de încredere.'],['h2','Unde se poate decide partida'],['p','Presiunea este diferită pentru fiecare echipă, dar duelul poate fi influențat de tranziții și de eficiența primelor faze de posesie. Tottenham are avantajul terenului propriu, însă Villa a arătat că poate controla perioade importante ale unui meci.']]},
{id:'pl-brighton-arsenal',cat:'Premier League',code:'PL',date:'19 septembrie 2026',title:'Brighton – Arsenal: campioana merge pe Amex într-un test de ritm',dek:'Arsenal intră în etapa a cincea cu obiectivul de a continua startul foarte bun de sezon.',source:'Premier League / NBC Sports',url:'https://www.nbcsports.com/soccer/news/premier-league-schedule-for-2026-27-season-released',body:[['p','Brighton primește vizita lui Arsenal în etapa a cincea. Programul oficial confirmă partida pentru 19 septembrie, iar campioana se deplasează la Amex după un început de sezon care a ridicat așteptările.'],['h2','Un test pentru controlul jocului'],['p','Brighton este genul de adversar care poate pedepsi pierderile de minge și spațiile dintre linii. Pentru Arsenal, cheia este să transforme controlul posesiei în ocazii clare fără să ofere gazdelor tranziții ușoare.']]},
{id:'pl-man-city-sunderland',cat:'Premier League',code:'PL',date:'19 septembrie 2026',title:'Manchester City – Sunderland: favorita trebuie să confirme statutul de gazdă',dek:'City primește nou-promovata Sunderland într-un meci care completează programul de sâmbătă.',source:'NBC Sports',url:'https://www.nbcsports.com/soccer/news/premier-league-schedule-for-2026-27-season-released',body:[['p','Manchester City întâlnește Sunderland pe teren propriu în etapa a cincea. Programul oficial al Premier League plasează partida în blocul de meciuri de la ora 16:00, ora României.'],['h2','Diferența de ritm și posesie'],['p','City va încerca să împingă adversarul cât mai jos și să creeze superiorități în jurul careului. Pentru Sunderland, rezistența fără minge și ieșirile rapide pot fi esențiale.']]},
{id:'ll-barcelona-seven',cat:'La Liga',code:'LL',date:'16 septembrie 2026',title:'Barcelona 7-2 Racing Santander: recital ofensiv pe Montjuïc',dek:'Barcelona a marcat de șapte ori și a oferit unul dintre cele mai spectaculoase scoruri ale începutului de sezon.',source:'Digi Sport',url:'https://www.digisport.ro/fotbal/la-liga/barcelona-n-a-avut-mila-de-santander-9-goluri-pe-camp-nou-hat-trick-raphinha-yamal-a-marcat-dar-a-ratat-si-un-penalty-4489409',body:[['p','Barcelona a trecut cu 7-2 de Racing Santander într-o partidă în care ofensiva catalană a produs ocazii în serie. Raphinha a fost unul dintre oamenii meciului, iar Lamine Yamal a înscris și a ratat un penalty.'],['h2','Barça își păstrează ritmul ofensiv'],['p','Victoria a venit după o serie de meciuri în care Barcelona a căutat să își impună ritmul prin posesie și presiune. Cele șapte goluri arată cât de repede poate crește avantajul atunci când echipa găsește spațiile potrivite.']]},
{id:'ll-sevilla-barca',cat:'La Liga',code:'LL',date:'19 septembrie 2026',title:'Sevilla – Barcelona: test pentru campioană după 7-2 cu Racing',dek:'Catalanii merg la Sevilla într-un meci care poate confirma sau tempera startul ofensiv.',source:'LALIGA',url:'https://www.laliga.com/en-ES/laliga-easports/results',body:[['p','Sevilla și Barcelona se întâlnesc sâmbătă seara, în etapa a șaptea din La Liga. Programul oficial LALIGA confirmă ora 21:00 pentru duelul de pe terenul Sevillei.'],['h2','Un alt tip de test'],['p','După un succes cu șapte goluri, Barcelona trebuie să gestioneze un meci în deplasare în care adversarul va încerca să reducă spațiile. Controlul ritmului și eficiența în primele minute pot conta mult.']]},
{id:'ll-athletic-alaves',cat:'La Liga',code:'LL',date:'19 septembrie 2026',title:'Athletic Club – Alavés: duel basc cu miză de clasament',dek:'San Mamés găzduiește unul dintre duelurile regionale ale etapei a șaptea.',source:'LALIGA',url:'https://www.laliga.com/en-ES/laliga-easports/results',body:[['p','Athletic Club și Deportivo Alavés se întâlnesc pe 19 septembrie, la 16:15. Partida este inclusă în programul oficial LALIGA pentru etapa a șaptea.'],['h2','Intensitate și dueluri directe'],['p','Meciurile dintre echipele din aceeași zonă geografică au adesea un ritm aparte, iar San Mamés poate pune presiune suplimentară pe oaspeți. Primele dueluri și fazele fixe pot deveni decisive.']]},
{id:'ll-atletico-real',cat:'La Liga',code:'LL',date:'20 septembrie 2026',title:'Atlético – Real Madrid: derby-ul Madridului vine duminică',dek:'Unul dintre cele mai importante meciuri ale etapei a șaptea se joacă pe 20 septembrie.',source:'LALIGA',url:'https://www.laliga.com/en-ES/laliga-easports/results',body:[['p','Atlético Madrid și Real Madrid se întâlnesc duminică, la 16:15, într-un derby care poate schimba rapid dinamica din partea superioară a clasamentului. Programul este confirmat de LALIGA.'],['h2','Meci în care detaliile au greutate'],['p','Derby-ul pune față în față două stiluri care pot produce perioade foarte diferite de joc. Gestionarea tranzițiilor și a fazelor fixe va fi una dintre cheile duelului.']]},
{id:'bl-bayern-seven',cat:'Bundesliga',code:'BL',date:'18 septembrie 2026',title:'Bayern 7-0 Union Berlin: campioana a deschis etapa cu un recital',dek:'Bayern a marcat de șapte ori și a oferit o demonstrație ofensivă în fața lui Union.',source:'Ahram Online / Bundesliga',url:'https://english.ahram.org.eg/News/576878.aspx',body:[['p','Bayern München a învins Union Berlin cu 7-0, deschizând etapa a patra din Bundesliga cu un rezultat categoric. Meciul a oferit gazdelor spațiu pentru a-și demonstra superioritatea ofensivă.'],['h2','Kane continuă să producă repere'],['p','Harry Kane a înscris și a rămas în centrul atenției după ce Bundesliga a consemnat apropierea și apoi atingerea unor borne istorice pentru atacantul englez.']]},
{id:'bl-kane-100',cat:'Bundesliga',code:'BL',date:'18 septembrie 2026',title:'Harry Kane: 100 de goluri în Bundesliga în doar 98 de apariții',dek:'Atacantul lui Bayern a doborât recordul pentru cea mai rapidă atingere a bornei de 100 de goluri.',source:'Bundesliga.com',url:'https://www.bundesliga.com/en/bundesliga/news/harry-kane-100-goals-record-stuttgart-schalke-union-berlin-38258',body:[['p','Harry Kane a ajuns la 100 de goluri în Bundesliga în numai 98 de apariții. Recordul anterior, deținut de Dieter Müller, era de 129 de meciuri.'],['h2','O bornă care rescrie recordurile'],['p','Diferența de 31 de apariții dintre Kane și recordul precedent subliniază eficiența atacantului în primele sale sezoane în Germania. Bayern beneficiază de un marcator capabil să transforme un volum mare de ocazii în goluri.']]},
{id:'bl-stuttgart-dortmund',cat:'Bundesliga',code:'BL',date:'19 septembrie 2026',title:'Stuttgart – Dortmund: meciul serii în Bundesliga',dek:'Două formații cu obiective mari se întâlnesc sâmbătă, iar piața indică un duel echilibrat.',source:'Bundesliga / Oddschecker',url:'https://www.oddschecker.com/us/soccer/bundesliga/vfb-stuttgart-v-borussia-dortmund',body:[['p','VfB Stuttgart și Borussia Dortmund se întâlnesc sâmbătă, la 18:30 ora Germaniei, într-unul dintre meciurile importante ale etapei. Bundesliga a publicat formulele probabile și lista absențelor înaintea partidei.'],['h2','Două echipe care pot produce ritm'],['p','Stuttgart are avantajul terenului propriu, în timp ce Dortmund vine cu un lot capabil să amenințe în tranziție. Cotele disponibile online au rămas apropiate, ceea ce reflectă un meci fără diferență mare de preț între cele două echipe.']]},
{id:'bl-frankfurt-freiburg',cat:'Bundesliga',code:'BL',date:'19 septembrie 2026',title:'Frankfurt – Freiburg: două formule cu absențe înaintea duelului',dek:'Bundesliga a publicat echipele probabile și absențele pentru partida de sâmbătă.',source:'Bundesliga.com',url:'https://www.bundesliga.com/en/bundesliga/news/team-news-line-ups-2026-27-bayern-dortmund-fantasy-20707',body:[['p','Eintracht Frankfurt și Freiburg se întâlnesc în etapa a patra. Informațiile oficiale de dinaintea partidei indică mai multe absențe în ambele loturi.'],['h2','Impactul indisponibilităților'],['p','Într-un campionat în care diferențele sunt mici, lipsa unor jucători de rotație sau de prim 11 poate modifica planul de joc. Frankfurt va încerca să folosească avantajul terenului pentru a impune ritmul.']]},
{id:'sa-roma-inter',cat:'Serie A',code:'SA',date:'19 septembrie 2026',title:'Roma – Inter: duel pentru primul loc pe Olimpico',dek:'Ambele echipe au maximum de puncte după patru etape și se întâlnesc în cel mai așteptat meci al rundei.',source:'Lega Serie A',url:'https://www.legaseriea.it/serie-a/news/roma-inter-vale-il-primato-solitario',body:[['p','Roma și Inter au câte 12 puncte după primele patru etape. Duelul de pe Olimpico este primul mare test direct pentru cele două echipe în noul sezon.'],['h2','Gasperini contra lui Chivu'],['p','Roma a primit un singur gol în primele patru etape, în timp ce Inter a înscris 13. Partida pune față în față două formații cu start perfect și doi antrenori care au construit identități diferite pentru echipele lor.']]},
{id:'sa-inter-udinese',cat:'Serie A',code:'SA',date:'14 septembrie 2026',title:'Inter 5-3 Udinese: revenire spectaculoasă și încă trei puncte pentru Chivu',dek:'Inter a întors un meci în care a fost condusă cu două goluri și a rămas la vârful clasamentului.',source:'Reuters',url:'https://www.reuters.com/sports/soccer/inter-rally-past-udinese-stay-level-with-roma-serie-summit-2026-09-14/',body:[['p','Inter a revenit de la 0-2 și a învins Udinese cu 5-3, păstrându-și startul perfect în Serie A. Rezultatul a dus echipa lui Cristian Chivu la 12 puncte după patru etape.'],['h2','Reacție ofensivă după începutul slab'],['p','Carlos Augusto, Barella, Thuram, Francesco Esposito și Bonny au marcat pentru Inter. Victoria a menținut echipa la egalitate de puncte cu Roma înaintea duelului direct de pe Olimpico.']]},
{id:'sa-bologna-torino',cat:'Serie A',code:'SA',date:'19 septembrie 2026',title:'Bologna – Torino: duel cu prețuri apropiate în piața 1X2',dek:'Partida de sâmbătă deschide programul zilei în Serie A, iar piața vede gazdele cu un avantaj moderat.',source:'Oddschecker',url:'https://www.oddschecker.com/football/italy/serie-a/bologna-v-torino/winner',body:[['p','Bologna și Torino se întâlnesc sâmbătă în Serie A. Snapshot-urile de cote consultate online au plasat victoria gazdelor în jurul cotei 1,90, remiza la aproximativ 3,45, iar succesul oaspeților în zona 4,00.'],['h2','Diferența de preț nu înseamnă automat diferență de valoare'],['p','Pentru o analiză serioasă, cota trebuie comparată cu probabilitatea estimată din datele sportive. O variație între operatori este relevantă pentru price shopping, dar nu este singură suficientă pentru a demonstra value.']]},
{id:'sa-chivu-absente',cat:'Serie A',code:'SA',date:'18 septembrie 2026',title:'Cristi Chivu, cu probleme de lot înainte de Roma – Inter',dek:'Inter abordează derby-ul cu absențe importante anunțate înaintea deplasării pe Olimpico.',source:'Digi Sport',url:'https://www.digisport.ro/fotbal/serie-a/vesti-proaste-pentru-cristi-chivu-inaintea-derby-ului-cu-as-roma-3-jucatori-out-4493501',body:[['p','Cristian Chivu pregătește meciul cu Roma într-un context în care lotul nu este complet. Informațiile publicate înaintea partidei indică absențe importante, care pot influența formula de start.'],['h2','Derby-ul vine după un început perfect'],['p','Inter are patru victorii în primele patru etape. Pentru Chivu, meciul de pe Olimpico este un test de gestionare a lotului într-un moment în care echipa a produs deja o revenire spectaculoasă la Udinese.']]},
{id:'ucl-md1',cat:'Champions League',code:'CL',date:'10 septembrie 2026',title:'Champions League: rezultate spectaculoase în prima etapă',dek:'Real Madrid, Barcelona, Bayern și PSG au început faza ligii cu victorii convingătoare.',source:'UEFA',url:'https://www.uefa.com/uefachampionsleague/news/02a8-2174c9e9019d-f909a77bd77a-1000--2026-27-champions-league-all-the-league-phase-fixtures/',body:[['p','Prima etapă a fazei ligii din Champions League 2026/27 s-a încheiat pe 10 septembrie. Real Madrid a învins Inter cu 2-1, Barcelona a trecut de Feyenoord cu 5-1, iar Bayern a câștigat cu 5-0 contra lui Bodø/Glimt.'],['h2','Arsenal a început cu victorie la Napoli'],['p','Arsenal s-a impus cu 1-0 la Napoli, în timp ce Manchester City a câștigat cu 2-0 la Porto. Faza ligii revine în octombrie, când programul include noi dueluri de top.']]},
{id:'ucl-next',cat:'Champions League',code:'CL',date:'13 octombrie 2026',title:'Champions League revine cu Arsenal – Lille și Roma – Real Madrid',dek:'Etapa a doua a fazei ligii începe în octombrie și aduce imediat dueluri importante.',source:'UEFA',url:'https://www.uefa.com/uefachampionsleague/news/02a8-2174c9e9019d-f909a77bd77a-1000--2026-27-champions-league-all-the-league-phase-fixtures/',body:[['p','UEFA a confirmat programul fazei ligii. Pe 13 și 14 octombrie sunt programate primele partide ale etapei a doua, inclusiv Arsenal – Lille și Roma – Real Madrid.'],['h2','Calendarul european se aglomerează'],['p','După etapa a doua urmează rapid dueluri precum Bayern – Arsenal pe 21 octombrie și Manchester City – PSG pe 14 octombrie. Pentru cluburile europene, gestionarea loturilor va deveni esențială.']]},
{id:'el-md1',cat:'Europa League',code:'EL',date:'17 septembrie 2026',title:'Europa League: Juventus, Beșiktaș și Crystal Palace au început cu victorii',dek:'Prima etapă a fazei ligii a oferit rezultate spectaculoase și două victorii cu români titulari.',source:'UEFA',url:'https://www.uefa.com/uefaeuropaleague/news/02a8-2174cafa5bb6-82bbc20c9b92-1000--2026-27-europa-league-all-the-league-phase-fixtures-and-re/',body:[['p','Juventus a învins NEC cu 5-0, Beșiktaș a trecut de Marseille cu 4-1, iar Crystal Palace a câștigat cu 4-0 contra lui Lech Poznań. Prima etapă a avut și rezultate strânse, precum Omonia 1-0 Celta.'],['h2','Olaru și Corbu au debutat cu victorii'],['p','Darius Olaru și Marius Corbu au fost titulari în succesele echipelor lor. Union SG a câștigat cu 3-0 la Viktoria Plzen, iar Ferencváros s-a impus cu 3-1 la Celtic.']]},
{id:'el-next',cat:'Europa League',code:'EL',date:'15 octombrie 2026',title:'Europa League: următoarea etapă aduce dueluri precum Benfica – Celtic și Beșiktaș – Hoffenheim',dek:'Etapa a doua este programată pe 15 octombrie, după pauza internațională.',source:'UEFA',url:'https://www.uefa.com/uefaeuropaleague/news/02a8-2177782493b9-69ba3288701d-1000--europa-league-league-phase-fixtures-and-results-by-team/',body:[['p','Faza ligii din Europa League continuă pe 15 octombrie. Benfica primește Celtic, Beșiktaș merge la Hoffenheim, iar Bournemouth joacă acasă cu Sturm Graz.'],['h2','Meciuri de urmărit pentru români'],['p','Olaru, Corbu și ceilalți români implicați în competiție vor avea din nou ocazia să joace în meciuri europene importante. Programul complet este publicat de UEFA și poate fi urmărit etapă cu etapă.']]},
{id:'conference-craiova',cat:'Conference League',code:'CO',date:'15 octombrie 2026',title:'Universitatea Craiova – Getafe: debut românesc în faza ligii Conference League',dek:'Craiova începe aventura europeană pe teren propriu, pe 15 octombrie.',source:'UEFA',url:'https://www.uefa.com/uefaconferenceleague/news/02a8-2174cb200f25-b94693ddff4e-1000--2026-27-conference-league-all-the-league-phase-fixtures/',body:[['p','Universitatea Craiova va întâlni Getafe pe 15 octombrie, la 18:45 CET, în prima etapă a fazei ligii din Conference League. UEFA a confirmat programul competiției.'],['h2','Șase etape în faza ligii'],['p','Craiova mai are în program deplasări la Inter Escaldes și Kairat Almaty, precum și meciuri acasă cu Egnatia și Copenhagen. Un alt duel important va fi deplasarea la Brighton din 26 noiembrie.']]},
{id:'conference-format',cat:'Conference League',code:'CO',date:'14 septembrie 2026',title:'Conference League 2026/27: șase etape și finala la Istanbul',dek:'Noua ediție a competiției se întinde până la începutul lui iunie 2027.',source:'UEFA',url:'https://www.uefa.com/uefaconferenceleague/news/02a6-20d57d15f093-a90cf54c928f-1000--2026-27-conference-league-teams-dates-draws-format-final/',body:[['p','Faza ligii Conference League începe pe 15 octombrie și se încheie pe 17 decembrie 2026. Competiția are șase etape în această fază.'],['h2','Finala se joacă la Istanbul'],['p','UEFA a stabilit finala pentru 2 iunie 2027, la Beșiktaș Stadium din Istanbul. Universitatea Craiova se numără printre cele 36 de echipe din faza ligii.']]},
{id:'olaru-corbu',cat:'Românii în sport',code:'RO',date:'18 septembrie 2026',title:'Olaru și Corbu, titulari în victorii europene',dek:'Doi dintre internaționalii României au început titular în succesele din Europa League.',source:'iAM SPORT',url:'https://iamsport.ro/fotbal-international/europa-league/victorii-pentru-olaru-si-corbu-succese-categorice-pentru-besiktas-crystal-palace-si-juventus-rezultatele-zilei-din-europa-league-id56263.html',body:[['p','Darius Olaru și Marius Corbu au fost titulari în victorii obținute de Union SG și Ferencváros în prima etapă a Europa League. Olaru a evoluat 83 de minute, iar Corbu a fost integralist.'],['h2','Un început european bun'],['p','Pentru cei doi, minutele în faza ligii reprezintă o oportunitate importantă de a acumula experiență la nivel european și de a rămâne în atenția staffului naționalei.']]},
{id:'oradea-polo',cat:'Românii în sport',code:'RO',date:'18 septembrie 2026',title:'CSM Oradea începe cu victorie în preliminariile Ligii Campionilor la polo',dek:'Formația română a trecut de Spandau 04 după aruncările de la 5 metri.',source:'AGERPRES',url:'https://agerpres.ro/sport',body:[['p','CSM Oradea a debutat cu victorie în preliminariile Ligii Campionilor la polo pe apă masculin, trecând de Spandau 04 Berlin după aruncările de la 5 metri.'],['h2','Succes într-un duel echilibrat'],['p','Rezultatul oferă echipei românești un start important într-o competiție în care fiecare punct poate conta pentru calificarea mai departe.']]},
{id:'rugby-finala',cat:'Românii în sport',code:'RO',date:'18 septembrie 2026',title:'Dinamo și Timișoara s-au calificat în finala Ligii Naționale de rugby',dek:'Cele două echipe au câștigat semifinalele și se pregătesc pentru ultimul act.',source:'AGERPRES',url:'https://agerpres.ro/sport',body:[['p','CS Dinamo București și SCM USV Timișoara s-au calificat în finala Ligii Naționale de rugby. Dinamo a trecut de Baia Mare cu 39-20, iar Timișoara a învins Steaua cu 36-6.'],['h2','Finală între două echipe cu istorii puternice'],['p','Cele două semifinale au produs rezultate clare după reveniri și perioade de dominare. Finala va reuni două dintre formațiile importante ale rugbyului românesc.']]},
{id:'blanaru',cat:'Românii în sport',code:'RO',date:'17 septembrie 2026',title:'Alexia Blănaru, campioană națională la individual compus',dek:'Sportiva a câștigat titlul la Campionatele Naționale de gimnastică artistică de la Galați.',source:'AGERPRES',url:'https://agerpres.ro/sport',body:[['p','Alexia Elena Blănaru a câștigat titlul de campioană națională la individual compus la ediția a 79-a a Campionatelor Naționale de gimnastică artistică.'],['h2','Rezultat important înaintea următoarelor competiții'],['p','Titlul de la Galați reprezintă un reper important în calendarul intern și oferă un indicator al formei sportive înaintea următoarelor obiective internaționale.']]},

{id:'pl-tottenham-villa-result',cat:'Premier League',code:'PL',date:'19 septembrie 2026',title:'Tottenham 2-3 Aston Villa: revenire târzie, dar Spurs rămâne fără victorie',dek:'Aston Villa a câștigat la Londra după un meci cu cinci goluri și un final tensionat.',source:'The Guardian',url:'https://www.theguardian.com/football/live/2026/sep/19/tottenham-v-aston-villa-premier-league-live',body:[['p','Aston Villa s-a impus cu 3-2 pe terenul lui Tottenham într-unul dintre cele mai spectaculoase meciuri ale zilei din Premier League. Villa a construit un avantaj important, iar Tottenham a redus diferența în final, fără să mai poată egala.'],['h2','Villa a profitat de tranziții'],['p','Oaspeții au fost eficienți în momentele în care au recuperat mingea și au atacat spațiile. Tottenham a avut perioade de presiune, dar a plătit pentru ocaziile ratate și pentru momentele în care apărarea a fost expusă.'],['h2','Un rezultat care schimbă datele etapei'],['p','Victoria îi aduce lui Aston Villa un succes important în etapa a cincea, în timp ce Tottenham rămâne fără victorie în campionat după primele cinci runde.'] ]},
{id:'superliga-20-fixtures',cat:'Liga 1',code:'L1',date:'20 septembrie 2026',title:'SuperLiga, duminică: Voluntari – U Cluj și Dinamo – Farul',dek:'Etapa a 10-a continuă duminică cu două partide programate în prima și a doua parte a zilei.',source:'Digi Sport / LPF',url:'https://www.digisport.ro/fotbal/liga-1',body:[['p','Programul oficial al etapei a 10-a continuă duminică, 20 septembrie, cu FC Voluntari – Universitatea Cluj și Dinamo București – Farul Constanța. Cele două partide sunt importante pentru configurația clasamentului înaintea pauzei internaționale.'],['h2','Programul zilei'],['p','FC Voluntari – Universitatea Cluj este programat la 14:00, iar Dinamo – Farul la 21:00, conform programului publicat pentru etapa a 10-a.'],['h2','Miză diferită, aceeași presiune'],['p','Pentru fiecare echipă, punctele pot conta în funcție de obiectivele de sezon. Dinamo și Farul au în plus un duel direct care poate schimba rapid pozițiile din zona superioară și mediană a clasamentului.']]},
{id:'pl-20-liverpool',cat:'Premier League',code:'PL',date:'20 septembrie 2026',title:'Bournemouth – Liverpool: campioana merge pe Vitality într-o zi aglomerată',dek:'Liverpool este programată duminică într-o etapă care mai include Manchester City – Sunderland și Fulham – Manchester United.',source:'Premier League',url:'https://www.premierleague.com/en/news/4675097/all-380-fixtures-for-202627-premier-league-season',body:[['p','Duminică, 20 septembrie, Bournemouth primește vizita lui Liverpool, într-o partidă programată în etapa a cincea din Premier League. Programul oficial al ligii confirmă meciul pentru ziua de duminică.'],['h2','O zi cu patru partide în Premier League'],['p','În aceeași zi sunt programate Manchester City – Sunderland, Leeds – Crystal Palace și Fulham – Manchester United. Pentru Liverpool, deplasarea la Bournemouth vine într-un weekend în care clasamentul se poate modifica prin rezultatele directe.'],['h2','Ce merită urmărit'],['p','Ritmul de posesie, presiunea după pierderea mingii și eficiența în primele faze de atac vor fi elemente importante într-un meci în care gazdele pot încerca să profite de tranziții.']]},
{id:'pl-20-city-sunderland',cat:'Premier League',code:'PL',date:'20 septembrie 2026',title:'Manchester City – Sunderland: meciul a fost mutat pentru duminică',dek:'Partida de pe Etihad nu se mai joacă sâmbătă; Premier League a confirmat reprogramarea pentru 20 septembrie.',source:'Premier League',url:'https://www.premierleague.com/en/news/4699026/manchester-city-v-sunderland-match-moved-to-a-new-date',body:[['p','Manchester City – Sunderland a fost mutat oficial de pe 19 pe 20 septembrie din cauza programului din Cupa Ligii. Premier League a confirmat noua dată, iar partida se joacă duminică.'],['h2','De ce s-a schimbat programul'],['p','Reprogramarea a fost făcută pentru a acomoda calendarul EFL Cup. Modificarea trebuie urmărită și în agregatoarele de rezultate, deoarece unele pagini păstrează inițial data publicată la începutul sezonului.'],['h2','Unul dintre meciurile centrale ale zilei'],['p','City – Sunderland este unul dintre cele patru meciuri de Premier League programate duminică, alături de Bournemouth – Liverpool, Leeds – Crystal Palace și Fulham – Manchester United.']]},
{id:'seriea-20-juve-atalanta',cat:'Serie A',code:'SA',date:'20 septembrie 2026',title:'Juventus – Atalanta: duel important în etapa a cincea din Serie A',dek:'Torinezii întâlnesc Atalanta duminică, într-un program care mai include Fiorentina – Napoli și Milan – Lecce.',source:'Serie A / Flashscore',url:'https://www.flashscore.com/match/football/atalanta-8C9JjMXu/juventus-C06aJvIB/',body:[['p','Juventus și Atalanta se întâlnesc duminică, 20 septembrie, în etapa a cincea din Serie A. Partida este programată după meciurile Fiorentina – Napoli, Frosinone – Como și Parma – Genoa.'],['h2','Programul complet al zilei'],['p','În aceeași zi mai sunt programate AC Milan – Lecce, iar campionatul italian intră în pauza internațională după această rundă.'],['h2','Un duel care cere atenție la tranziții'],['p','Ambele echipe au capacitatea de a accelera după recuperare, astfel că duelurile de la mijlocul terenului și protejarea spațiilor dintre linii pot influența desfășurarea partidei.']]},
{id:'laliga-20-atletico-real',cat:'La Liga',code:'LL',date:'20 septembrie 2026',title:'Atlético Madrid – Real Madrid: derby-ul de duminică',dek:'Metropolitano găzduiește derby-ul Madridului în etapa a șaptea din La Liga.',source:'LALIGA / Sport.ro',url:'https://www.sport.ro/fotbal/rezultate-live/2026-09-20',body:[['p','Atlético Madrid și Real Madrid se întâlnesc duminică, 20 septembrie, într-un derby programat în etapa a șaptea din La Liga. Meciul este unul dintre principalele puncte de interes ale weekendului fotbalistic.'],['h2','Derby cu miză tactică'],['p','Atlético va încerca să controleze spațiile și să transforme recuperările în atacuri rapide, în timp ce Real Madrid poate căuta progresia prin posesie și atacarea zonelor laterale.'],['h2','Restul programului La Liga'],['p','Duminică mai sunt programate Getafe – Málaga, Villarreal – Levante, Deportivo La Coruña – Real Betis și Valencia – Real Sociedad.']]},
{id:'bundesliga-20-leipzig',cat:'Bundesliga',code:'BL',date:'20 septembrie 2026',title:'Leverkusen – RB Leipzig: duel de duminică în Bundesliga',dek:'Etapa a patra se încheie cu trei partide duminică, inclusiv Leverkusen – Leipzig.',source:'Bundesliga.com',url:'https://www.bundesliga.com/en/bundesliga/news/team-news-line-ups-2026-27-bayern-dortmund-fantasy-20707',body:[['p','Bayer Leverkusen și RB Leipzig se întâlnesc duminică în etapa a patra din Bundesliga. Bundesliga a publicat informațiile despre loturi și absențe înaintea meciului.'],['h2','Absențe de urmărit'],['p','Leipzig are mai mulți jucători indisponibili sau incerți, iar Leverkusen are la rândul său câteva probleme de lot. Situația poate influența formula de start și rotația.'],['h2','Celelalte meciuri'],['p','Schalke – Elversberg și Paderborn – Hoffenheim completează programul de duminică din eșalonul secund și Bundesliga, după caz, în funcție de competiție.']]},
{"id":"superliga-etapa14-rezultate-2nov","cat":"Liga 1","code":"L1","date":"2 noiembrie 2026","title":"SuperLiga, etapa a 14-a: Dinamo câștigă, Craiova trece de Botoșani, iar Corvinul ia trei puncte","dek":"LPF confirmă rezultatele: Rapid 2-0 Csíkszereda, Corvinul 2-0 FC Argeș, Petrolul 1-1 CFR, Craiova 2-1 Botoșani, Dinamo 2-0 UTA, Farul 2-1 Voluntari și U Cluj 1-0 FCSB.","source":"LPF","url":"https://lpf.ro/liga-1","body":[["p","Etapa a 14-a din SuperLiga a adus rezultate importante în lupta pentru primele locuri. Potrivit programului și rezultatelor publicate de Liga Profesionistă de Fotbal, Rapid a învins FK Csíkszereda cu 2-0, Corvinul Hunedoara a trecut de FC Argeș cu 2-0, iar Petrolul și CFR Cluj au remizat, 1-1."],["h2","Rezultatele de duminică"],["p","Oțelul Galați și Sepsi OSK au încheiat la egalitate, 1-1. Universitatea Craiova a învins FC Botoșani cu 2-1, iar Dinamo a câștigat cu UTA Arad, scor 2-0. Luni, Farul a învins FC Voluntari cu 2-1, iar Universitatea Cluj a trecut de FCSB cu 1-0, completând etapa."],["h2","Corvinul, rezultat de urmărit"],["p","Succesul cu 2-0 în fața lui FC Argeș este unul dintre rezultatele rundei pentru fotbalul hunedorean. Rezultatele complete și clasamentul actualizat sunt disponibile pe pagina oficială LPF."]]},
{"id":"ucl-etapa4-analiza-2nov","cat":"Champions League","code":"UCL","date":"2 noiembrie 2026","title":"Champions League revine cu etapa a patra: 18 meciuri în două seri","dek":"UEFA a confirmat programul din 3 și 4 noiembrie. Barcelona – Aston Villa și Atlético – Bayern sunt printre duelurile de marți.","source":"UEFA","url":"https://www.uefa.com/uefachampionsleague/news/02a8-2174c9e9019d-f909a77bd77a-1000--2026-27-champions-league-all-the-league-phase-fixtures-and-results/","body":[["p","Etapa a patra a fazei ligii UEFA Champions League se dispută marți, 3 noiembrie, și miercuri, 4 noiembrie. Calendarul oficial UEFA listează 18 partide, iar orele sunt exprimate în CET."],["h2","Marți: dueluri de prim-plan"],["p","Programul zilei include Shakhtar Donetsk – Sporting CP și Galatasaray – Stuttgart, ambele la 18:45 CET. În intervalul de seară sunt programate Atlético de Madrid – Bayern München, Barcelona – Aston Villa, Feyenoord – Inter, Manchester United – Roma și Villarreal – Paris Saint-Germain."],["h2","Miercuri: Liverpool, Real Madrid și Arsenal"],["p","Miercuri, Fenerbahçe – Liverpool și AEK Athens – Real Madrid încep la 18:45 CET. Restul programului include Borussia Dortmund – Real Betis, Porto – Napoli, PSV – Club Brugge, Leipzig – Manchester City, Lens – Como, Slavia Praha – Arsenal și Viking – Sabah."],["h2","Ce este confirmat și ce nu"],["p","Programul și rezultatele etapelor precedente sunt confirmate de UEFA. În acest material nu atribuim absențe, titulari sau declarații niciunei echipe fără comunicate oficiale separate. Clasamentul fazei ligii trebuie consultat în pagina competiției înainte de fiecare partidă."]]},
{"id":"europa-league-etapa4-noiembrie","cat":"Europa League","code":"UEL","date":"2 noiembrie 2026","title":"Europa League: Milan – Ferencváros și Juventus – AZ, capete de afiș în etapa a patra","dek":"UEFA a publicat programul rundei din 5 noiembrie, cu 18 partide în faza ligii.","source":"UEFA","url":"https://www.uefa.com/uefaeuropaleague/news/02a8-2174cafa5bb6-82bbc20c9b92-1000--2026-27-europa-league-all-the-league-phase-fixtures-and-results/","body":[["p","Etapa a patra a fazei ligii UEFA Europa League este programată joi, 5 noiembrie 2026. Calendarul oficial UEFA include 18 confruntări, cu primele partide începând la 18:45 CET."],["h2","Meciurile de la 18:45 CET"],["p","Printre jocurile programate la 18:45 se află Milan – Ferencváros, Sparta Praha – Bournemouth, Crystal Palace – Hoffenheim, Lillestrøm – Viktoria Plzeň, N.E.C. Nijmegen – Omonia, Levski Sofia – Jagiellonia și Real Sociedad – Lyon."],["h2","Dueluri programate în sesiunea de seară"],["p","Programul UEFA mai include AZ Alkmaar – Juventus, Bayer Leverkusen – Marseille, Celtic – Beşiktaş, Celta – Union SG, Benfica – Lech Poznań și Sunderland – GNK Dinamo. Ora exactă trebuie verificată în pagina meciului înainte de publicare sau de start."],["h2","Contextul competiției"],["p","Faza ligii a început în septembrie și se încheie în ianuarie 2027. Rezultatele etapelor precedente sunt disponibile în pagina UEFA; pentru această avancronică folosim exclusiv programul publicat de organizator, fără a inventa statistici de formă sau informații medicale."]]},
{"id":"conference-craiova-egnatia-avancr","cat":"Conference League","code":"UECL","date":"2 noiembrie 2026","title":"Universitatea Craiova – Egnatia: oltenii joacă joi pentru puncte europene","dek":"UEFA confirmă duelul din 5 noiembrie, în etapa a treia a fazei ligii Conference League.","source":"UEFA","url":"https://www.uefa.com/uefaconferenceleague/news/02a8-2174cb200f25-b94693ddff4e-1000--202627-conference-league-all-the-league-phase-fixtures/","body":[["p","Universitatea Craiova întâlnește formația albaneză Egnatia joi, 5 noiembrie, în etapa a treia a fazei ligii UEFA Conference League. Partida apare în calendarul oficial al competiției."],["h2","Ce s-a întâmplat în primele două etape"],["p","În prima rundă, Universitatea Craiova a remizat acasă cu Getafe, 1-1. În etapa a doua, echipa română a câștigat în deplasare cu Inter Escaldes, scor 3-1, potrivit rezultatelor listate de UEFA."],["h2","O rundă cu adversari puternici"],["p","Programul etapei a treia include și Atalanta – Kairat Almaty, Midtjylland – Ajax, Trabzonspor – Freiburg și Getafe – Brighton. Pentru ora exactă a meciului Craiovei și eventualele modificări, trebuie consultată pagina oficială UEFA a partidei."],["h2","Prudență înaintea jocului"],["p","Nu publicăm formula probabilă, indisponibilități sau cote fără confirmări distincte. Singurele elemente prezentate ca certe aici sunt programarea și rezultatele anterioare publicate de UEFA."]]},
{"id":"nationala-romaniei-noiembrie-program","cat":"Naționala","code":"RO","date":"2 noiembrie 2026","title":"România intră în luna decisivă din Nations League: Polonia și Bosnia urmează în noiembrie","dek":"UEFA confirmă meciurile României din 14 și 17 noiembrie; FRF a publicat lista preliminară a stranierilor.","source":"UEFA și FRF","url":"https://www.uefa.com/uefanationsleague/teams/113/matches/","body":[["p","Naționala României are programate două partide în noiembrie, în faza grupelor UEFA Nations League: întâlnește Polonia pe 14 noiembrie, apoi joacă în deplasare cu Bosnia și Herțegovina pe 17 noiembrie. Calendarul este confirmat de pagina UEFA dedicată echipei naționale."],["h2","Lista preliminară nu este lotul final"],["p","FRF a publicat lista convocărilor preliminare pentru stranierii aflați în atenția selecționerului Gheorghe Hagi. Federația precizează că lista este preliminară, iar lotul final va include și jucători din competiția internă. Prin urmare, lista nu trebuie prezentată ca o convocare definitivă."],["h2","Ce urmează pentru redacție"],["p","Următorul reper editorial este anunțarea lotului final și conferința de presă premergătoare reunirii. Până la comunicarea oficială, nu publicăm titulari probabili, absențe suplimentare sau declarații atribuite staffului tehnic."]]},
{"id":"premier-league-program-6-8nov","cat":"Premier League","code":"PL","date":"2 noiembrie 2026","title":"Premier League: programul etapei din 6–8 noiembrie aduce Everton – Coventry și United – Villa","dek":"Liga engleză a publicat orele revizuite pentru meciurile din primul weekend complet al lunii noiembrie.","source":"Premier League","url":"https://www.premierleague.com/en/news/4725574","body":[["p","Premier League a confirmat programul revizuit al meciurilor din noiembrie, după selecțiile pentru transmisiunile TV și ajustările generate de participarea cluburilor în competițiile UEFA."],["h2","Vineri și sâmbătă"],["p","Vineri, 6 noiembrie, Everton întâlnește Coventry de la 20:00 GMT. Sâmbătă, 7 noiembrie, sunt programate Leeds – Tottenham la 12:30 GMT și Nottingham Forest – Manchester City la 17:30 GMT; în aceeași zi se joacă și Arsenal – Hull City, respectiv Fulham – Newcastle."],["h2","Duminică: United – Aston Villa"],["p","Duminică, 8 noiembrie, Brighton – Brentford, Crystal Palace – Liverpool, Ipswich – Bournemouth și Sunderland – Chelsea sunt programate la 14:00 GMT. Manchester United – Aston Villa încheie ziua la 16:30 GMT."],["h2","Orele și fusurile orare"],["p","Premier League publică orele în GMT. Pentru cititorii din România, conversia trebuie făcută ținând cont de fusul orar local; în noiembrie, România este cu două ore înaintea GMT. Programul poate suferi modificări, astfel că pagina oficială rămâne referința finală."]]},
{"id":"laliga-etapa12-calendar","cat":"La Liga","code":"LL","date":"2 noiembrie 2026","title":"LaLiga: etapa a 12-a este programată pe 8 noiembrie, înaintea pauzei internaționale","dek":"Calendarul oficial al ligii spaniole listează următoarea rundă pentru 8 noiembrie și următoarea etapă pentru 22 noiembrie.","source":"LALIGA","url":"https://www.laliga.com/calendar-2026-2027/laliga-easports","body":[["p","Calendarul oficial LALIGA pentru sezonul 2026/27 indică etapa a 12-a la data de 8 noiembrie și etapa a 13-a pe 22 noiembrie. Programul este afișat în perechi de echipe, iar orele și ordinea completă a partidelor trebuie verificate în pagina fiecărui meci."],["h2","Dueluri programate în etapa a 12-a"],["p","Printre perechile listate în calendar pentru 8 noiembrie se află Atlético de Madrid – FC Barcelona, RC Celta – Levante UD, Elche – Real Betis, Espanyol – Deportivo, Osasuna – Athletic Club, Real Sociedad – Rayo Vallecano, Sevilla – Alavés, Real Madrid – Valencia și Villarreal – Getafe."],["h2","Ce înseamnă pentru cursa din campionat"],["p","Etapa oferă un nou reper în calendar, dar nu tragem concluzii despre clasament sau forma echipelor fără un tabel actualizat și rezultate confirmate după încheierea rundei precedente. Înainte de avancronici individuale, vom verifica ora, stadionul și loturile în sursele cluburilor și ale ligii."]]},
{"id":"bundesliga-etapa9-program","cat":"Bundesliga","code":"BUN","date":"2 noiembrie 2026","title":"Bundesliga: Bayern merge la Mainz, iar etapa a noua se joacă între 6 și 8 noiembrie","dek":"Calendarul oficial al competiției confirmă programul rundei, inclusiv Mainz – Bayern și Köln – Leverkusen.","source":"Bundesliga","url":"https://products.bundesliga.com/fixtures","body":[["p","Programul oficial al Bundesliga pentru etapa a noua începe vineri, 6 noiembrie, și se încheie duminică, 8 noiembrie. Lista publicată de organizator confirmă datele, orele și perechile de echipe."],["h2","Meciurile principale ale rundei"],["p","Vineri, Hamburger SV întâlnește Borussia Mönchengladbach la 20:30 CET. Sâmbătă, Borussia Dortmund joacă împotriva lui Elversberg, RB Leipzig primește Augsburg, iar Mainz întâlnește Bayern München; toate trei sunt programate la 15:30 CET. Stuttgart – Werder Bremen este programat la 18:30 CET."],["h2","Duminică încheie etapa"],["p","Duminică, 8 noiembrie, Köln – Bayer Leverkusen este programat la 15:30 CET, Freiburg – Union Berlin la 17:30 CET, iar Hoffenheim – Schalke la 19:30 CET."],["h2","Limitările acestei avancronici"],["p","Calendarul confirmă programul, nu forma sportivă, absențele sau primul unsprezece. Aceste elemente vor fi adăugate doar după consultarea rapoartelor de meci și a comunicatelor cluburilor."]]},
{"id":"seriea-noutati-calendar-noiembrie","cat":"Serie A","code":"SA","date":"2 noiembrie 2026","title":"Serie A: programul de noiembrie trebuie urmărit prin calendarul oficial al ligii","dek":"Redacția nu publică perechi sau ore pentru etapa următoare fără o confirmare primară verificabilă.","source":"Lega Serie A","url":"https://www.legaseriea.it/en/serie-a/fixtures-and-results","body":[["p","Pentru această ediție, pagina oficială Lega Serie A este sursa de referință pentru calendar, rezultate și clasament. În verificarea disponibilă pentru această ediție nu am putut confirma în mod suficient programul complet și orele următoarei runde, așa că nu publicăm o listă de meciuri construită din surse secundare."],["h2","De ce păstrăm standardul de verificare"],["p","O oră greșită sau o partidă mutată poate compromite o avancronică și poate induce cititorul în eroare, mai ales în rubrica de betting. Materialele individuale despre echipe vor fi publicate după confirmarea calendarului direct la organizator."],["h2","Actualizare editorială"],["p","Aceasta este o notă de transparență editorială, nu o știre despre un rezultat sportiv. Pagina va fi completată când calendarul și informațiile relevante pot fi verificate din surse primare."]]},
{"id":"romanii-in-sport-corvinul-2nov","cat":"Românii în sport","code":"RO","date":"2 noiembrie 2026","title":"Corvinul Hunedoara, rezultat important în etapa a 14-a: 2-0 cu FC Argeș","dek":"Formația hunedoreană a câștigat pe teren propriu, potrivit rezultatului publicat de LPF.","source":"LPF","url":"https://lpf.ro/liga-1","body":[["p","Corvinul Hunedoara a învins FC Argeș cu 2-0, sâmbătă, 31 octombrie, în etapa a 14-a din SuperLiga. Scorul este consemnat în programul oficial al Ligii Profesioniste de Fotbal."],["h2","Un rezultat pentru fotbalul hunedorean"],["p","Victoria aduce trei puncte formației din Hunedoara și reprezintă unul dintre rezultatele notabile ale rundei. Nu adăugăm marcatori sau minute ale golurilor în lipsa unei fișe de meci verificate în sursa primară consultată."],["h2","Urmărim parcursul echipei"],["p","Pentru următoarele materiale despre Corvinul, redacția va urmări programul oficial, clasamentul și comunicatele clubului. Rezultatul de 2-0 este confirmat de LPF; detaliile suplimentare vor fi publicate numai după verificare."]]},
{"id":"euro-2028-tragere-belfast","cat":"EURO","code":"EURO","date":"2 noiembrie 2026","title":"EURO 2028: tragerea la sorți a preliminariilor va avea loc la Belfast pe 6 decembrie","dek":"UEFA a confirmat data și locul tragerii la sorți; preliminariile vor începe în martie 2027.","source":"UEFA","url":"https://www.uefa.com/euro2028/news/029f-1f2ff991e87b-345fffcd69c3-1000/","body":[["p","UEFA a anunțat că tragerea la sorți a preliminariilor EURO 2028 va avea loc la Belfast, duminică, 6 decembrie 2026, la ora 18:00 CET. Evenimentul va stabili componența grupelor pentru drumul către turneul final."],["h2","Formatul preliminariilor"],["p","Potrivit UEFA, echipele vor fi repartizate în 12 grupe de câte patru sau cinci formații, care vor juca tur-retur. Faza grupelor este programată să înceapă în martie 2027 și să se încheie în noiembrie 2027."],["h2","Cum se califică echipele"],["p","Câștigătoarele grupelor se califică direct la turneul final. Pentru locurile secunde, UEFA prevede calificare directă sau participare la baraje, în funcție de configurația stabilită prin regulament și de traseul echipelor din Liga Națiunilor. Barajele sunt programate în martie 2028."],["h2","Ce urmează"],["p","Până la tragerea la sorți, nu există grupe preliminare pe care să le putem prezenta ca stabilite. Orice simulare de adversari ar fi speculativă și nu este inclusă în această știre."]]},
{"id":"nations-league-romania-noiembrie","cat":"Liga Națiunilor","code":"NL","date":"2 noiembrie 2026","title":"Liga Națiunilor: România – Polonia pe 14 noiembrie și Bosnia – România pe 17 noiembrie","dek":"UEFA confirmă ultimele două partide ale României în faza ligii, ambele decisive pentru încheierea grupei.","source":"UEFA","url":"https://www.uefa.com/uefanationsleague/teams/113/matches/","body":[["p","Calendarul oficial UEFA pentru Liga Națiunilor 2026/27 arată că România va juca împotriva Poloniei pe 14 noiembrie, apoi va întâlni Bosnia și Herțegovina în deplasare, pe 17 noiembrie. Ambele partide fac parte din ultimele două etape ale fazei ligii, care se încheie la 17 noiembrie."],["h2","Un final de grupă concentrat"],["p","Etapa a cincea este programată între 12 și 14 noiembrie, iar etapa a șasea între 15 și 17 noiembrie. În aceeași perioadă se joacă și alte dueluri importante în ligile A, B, C și D."],["h2","Nu anticipăm clasamentul final"],["p","Fără un tabel complet și actualizat după toate meciurile disputate, nu prezentăm scenarii de calificare ca fiind certe. Pentru România, următorul reper este comunicarea lotului final și apoi rezultatele celor două partide."]]},
{"id":"campionatul-mondial-2026-dupa-finala","cat":"Cupa Mondială","code":"WC","date":"2 noiembrie 2026","title":"Cupa Mondială 2026 s-a încheiat: FIFA păstrează arhiva oficială a turneului cu 48 de echipe","dek":"Turneul final s-a desfășurat între 11 iunie și 19 iulie 2026, cu 104 meciuri în 16 orașe-gazdă.","source":"FIFA","url":"https://www.fifa.com/en/tournaments/mens/worldcup/canadamexicousa2026/articles/match-schedule-fixtures-results-teams-stadiums","body":[["p","Cupa Mondială FIFA 2026 s-a desfășurat între 11 iunie și 19 iulie 2026, în Canada, Mexic și Statele Unite. Pagina oficială FIFA descrie ediția extinsă la 48 de echipe și 104 meciuri, disputate în 16 orașe-gazdă."],["h2","Unde se găsesc rezultatele și tabloul turneului"],["p","FIFA pune la dispoziție arhiva cu programul, rezultatele, grupele, tabloul fazelor eliminatorii și informațiile despre stadioane. În această ediție nu adăugăm un câștigător, un scor al finalei sau statistici individuale fără a putea confirma acele date în pagina oficială consultată."],["h2","Rubrica rămâne activă"],["p","După încheierea turneului, secțiunea va urmări bilanțurile oficiale, recordurile confirmate și pregătirea următoarei competiții internaționale. Orice statistică istorică va fi legată de raportul FIFA corespunzător."]]},
{"id":"betting-desk-analiza-ucl-3-4nov","cat":"Betting","code":"BET","date":"2 noiembrie 2026","title":"Betting Desk: trei meciuri de Champions League intră în analiză, dar nu există pariu fără preț verificat","dek":"Barcelona – Aston Villa, Atlético – Bayern și Fenerbahçe – Liverpool sunt meciuri de urmărit; selecțiile rămân condiționate de cote și verificări finale.","source":"UEFA; agregatoare publice de cote consultate la 2 noiembrie 2026","url":"https://www.uefa.com/uefachampionsleague/news/02a8-2174c9e9019d-f909a77bd77a-1000--2026-27-champions-league-all-the-league-phase-fixtures-and-results/","body":[["p","Pentru etapa a patra din Champions League am selectat trei partide pentru analiză: Barcelona – Aston Villa și Atlético de Madrid – Bayern München, marți, 3 noiembrie, respectiv Fenerbahçe – Liverpool, miercuri, 4 noiembrie. Programul este confirmat de UEFA. Selecția meciurilor pentru analiză nu reprezintă automat o recomandare de pariere."],["h2","Barcelona – Aston Villa: atenție la prețul favoritului"],["p","Cotele publice consultate pentru piața 1X2 indică Barcelona drept favorită clară. O cotă foarte mică pe victoria gazdelor poate avea un raport risc-preț slab chiar dacă probabilitatea estimată este ridicată. Fără o estimare independentă, ajustată pentru marja operatorului și informațiile de lot, nu declarăm această cotă value bet."],["h2","Atlético – Bayern: piață mai echilibrată"],["p","Sursele publice consultate arată o piață mai apropiată între cele două echipe, iar diferențele dintre operatori sunt vizibile. Tocmai de aceea, piața 1X2 nu trebuie tratată ca o selecție automată. Înainte de orice decizie sunt necesare confirmarea cotelor la operatorul autorizat în România, verificarea loturilor și compararea prețului cu o probabilitate proprie."],["h2","Fenerbahçe – Liverpool: favorită în deplasare, risc de context"],["p","Liverpool este cotată favorită în agregatoarele consultate, însă deplasarea la Istanbul introduce un context diferit față de un meci pe teren neutru. Nu folosim cotele agregatoarelor ca ofertă disponibilă în România și nu prezentăm o cotă ca garantat accesibilă la un operator local."],["h2","Verdictul redacției: watchlist, nu bilet"],["p","La verificarea din 2 noiembrie 2026 nu avem o sursă suficientă pentru a certifica simultan cota actuală la un operator licențiat ONJN și o probabilitate proprie robustă. Prin urmare, nu publicăm Cota zilei și nu recomandăm un bilet. Cele trei meciuri rămân în watchlist pentru analiză; dacă prețul scade sub pragul calculat sau informațiile de lot se schimbă, selecția trebuie reevaluată. Pariurile sunt 18+ și implică risc financiar."]]}
 ];
